import { assertEquals } from "https://deno.land/std@0.224.0/assert/mod.ts";
import { resolveFlowBranch, getMissingContactFields } from "./skipMatrix.ts";
import { parseContactReply } from "./parseContactReply.ts";
import { contactPromptForMissing } from "./contactGatePrompt.ts";
import { isPostContactGateEnrollmentStatus } from "../followGateRuntime.ts";

Deno.test("skipMatrix complete profile", () => {
  const branch = resolveFlowBranch({
    campaign: { contact_gate_enabled: true },
    profile: { phone_number: "6281", email: "a@b.com" },
    isFollower: true,
  });
  assertEquals(branch.branch, "deliver_instagram");
});

Deno.test("skipMatrix phone only needs email on next enrollment", () => {
  assertEquals(
    getMissingContactFields({ phone_number: "6281286663811", email: null }),
    "email",
  );
  const branch = resolveFlowBranch({
    campaign: { contact_gate_enabled: true },
    profile: { phone_number: "6281286663811", email: null },
    isFollower: true,
  });
  assertEquals(branch.branch, "needs_contact");
  if (branch.branch === "needs_contact") {
    assertEquals(branch.ask, "email");
  }
});

Deno.test("skipMatrix email only needs phone", () => {
  assertEquals(
    getMissingContactFields({ phone_number: null, email: "user@example.com" }),
    "phone",
  );
});

Deno.test("parseContactReply phone", () => {
  const r = parseContactReply("08123456789");
  assertEquals(r.kind, "phone");
});

Deno.test("parseContactReply email", () => {
  const r = parseContactReply("oktavialdidhanta@gmail.com");
  assertEquals(r.kind, "email");
  if (r.kind === "email") {
    assertEquals(r.normalized, "oktavialdidhanta@gmail.com");
  }
});

Deno.test("getMissingContactFields any", () => {
  assertEquals(getMissingContactFields({ phone_number: null, email: null }), "any");
});

Deno.test("contactPromptForMissing email uses dedicated template", () => {
  const text = contactPromptForMissing(
    { contact_gate_enabled: true } as Parameters<typeof contactPromptForMissing>[0],
    "email",
    "testuser",
  );
  assertEquals(text.includes("email Anda"), true);
  assertEquals(text.includes("testuser"), true);
});

Deno.test("delivered_whatsapp is terminal post-contact gate status", () => {
  assertEquals(isPostContactGateEnrollmentStatus("delivered_whatsapp"), true);
  assertEquals(isPostContactGateEnrollmentStatus("delivered_email"), true);
  assertEquals(isPostContactGateEnrollmentStatus("awaiting_contact"), true);
  assertEquals(isPostContactGateEnrollmentStatus("comment_replied"), false);
});

Deno.test("returning profile phone-only: email ask applies at new enrollment entry", () => {
  const missing = getMissingContactFields({
    phone_number: "6281286663811",
    email: null,
  });
  const parsed = parseContactReply("oktavialdidhanta@gmail.com");
  assertEquals(missing, "email");
  assertEquals(parsed.kind, "email");
});

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import type { MissingContactField } from "./skipMatrix.ts";
import { sendLeadMagnetDm } from "../sendLeadMagnetMessage.ts";
import { logLeadMagnetFunnelEvent, updateEnrollmentStatus } from "../funnelAnalytics.ts";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";
import { LEAD_MAGNET_DEFAULT_MESSAGES } from "../types.ts";

export const DEFAULT_CONTACT_PROMPT_BOTH =
  "Hai {{username}},\n\nTerima kasih atas minat Anda pada materi kami.\n\nUntuk mengirimkan file, silakan balas chat ini dengan:\n• Nomor WhatsApp aktif (contoh: 08123456789) — materi dikirim via WhatsApp, atau\n• Alamat email aktif (contoh: nama@perusahaan.com) — materi dikirim ke email Anda.\n\nKami hanya menggunakan kontak ini untuk pengiriman materi yang Anda minta.";

export const DEFAULT_CONTACT_PROMPT_PHONE =
  "Hai {{username}},\n\nAgar kami dapat mengirim materi langsung ke WhatsApp Anda, silakan balas chat ini dengan nomor WhatsApp aktif (contoh: 08123456789).\n\nMateri akan kami kirim melalui WhatsApp setelah nomor kami terima.";

export const DEFAULT_CONTACT_PROMPT_EMAIL =
  "Hai {{username}},\n\nAgar kami dapat mengirim materi ke email Anda, silakan balas chat ini dengan alamat email aktif (contoh: nama@perusahaan.com).\n\nMateri akan kami kirim ke inbox email setelah alamat kami terima.";

export const DEFAULT_CONTACT_INVALID =
  "Mohon maaf, format nomor atau email belum dapat kami baca.\n\nSilakan kirim nomor WhatsApp (contoh: 08123456789) atau email (contoh: nama@perusahaan.com).";

function needsFirstContactDm(enrollment: LeadMagnetEnrollmentRow): boolean {
  const commentId = enrollment.comment_id?.trim();
  if (commentId && !enrollment.private_reply_message_id) {
    return enrollment.platform === "instagram" || enrollment.platform === "facebook";
  }
  return !enrollment.conversation_id;
}

function interpolateCampaignText(template: string, username: string | null): string {
  const handle = (username ?? "").trim().replace(/^@/, "") || "Kak";
  return template.replace(/\{\{username\}\}/gi, handle);
}

const CONTACT_PROMPT_CLAIM_STATUSES = [
  "follow_validated",
  "material_offer_skipped",
  "contact_collected",
  "delivered_whatsapp",
  "delivered_email",
] as const;

const CONTACT_PROMPT_FORCE_CLAIM_STATUSES = [
  "follow_gate_sent",
  "follow_checked",
  "comment_replied",
  "comment_matched",
] as const;

async function lastContactPromptAsk(
  admin: SupabaseClient,
  enrollmentId: string,
): Promise<MissingContactField | null> {
  const { data } = await admin
    .from("lead_magnet_funnel_events")
    .select("metadata")
    .eq("enrollment_id", enrollmentId)
    .eq("event_type", "contact_prompt_sent")
    .order("created_at", { ascending: false })
    .limit(1)
    .maybeSingle();

  const ask = (data?.metadata as { ask?: string } | null)?.ask;
  if (ask === "any" || ask === "phone" || ask === "email") return ask;
  return null;
}

export function contactPromptForMissing(
  campaign: LeadMagnetCampaignRow,
  ask: MissingContactField,
  username: string | null,
): string {
  if (ask === "phone") {
    return interpolateCampaignText(DEFAULT_CONTACT_PROMPT_PHONE, username);
  }
  if (ask === "email") {
    return interpolateCampaignText(DEFAULT_CONTACT_PROMPT_EMAIL, username);
  }
  const base = campaign.contact_prompt_text?.trim()
    || LEAD_MAGNET_DEFAULT_MESSAGES.contact_prompt_text
    || DEFAULT_CONTACT_PROMPT_BOTH;
  return interpolateCampaignText(base, username);
}

export async function sendContactPrompt(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    accessToken: string;
    pageId: string;
    ask: MissingContactField;
  },
): Promise<boolean> {
  if (args.enrollment.status === "awaiting_contact") {
    const lastAsk = await lastContactPromptAsk(admin, args.enrollment.id);
    if (lastAsk === args.ask) return true;
  }

  const now = new Date().toISOString();
  let claimed = false;

  if (args.enrollment.status !== "awaiting_contact") {
    const { data: claimRow } = await admin
      .from("lead_magnet_enrollments")
      .update({ status: "awaiting_contact", updated_at: now })
      .eq("id", args.enrollment.id)
      .in("status", [...CONTACT_PROMPT_CLAIM_STATUSES])
      .select("id")
      .maybeSingle();

    claimed = Boolean(claimRow?.id);

    if (!claimed) {
      const forceClaim = await admin
        .from("lead_magnet_enrollments")
        .update({ status: "awaiting_contact", updated_at: now })
        .eq("id", args.enrollment.id)
        .in("status", [...CONTACT_PROMPT_FORCE_CLAIM_STATUSES])
        .select("id")
        .maybeSingle();
      claimed = Boolean(forceClaim.data?.id);
      if (!claimed) return false;
    }
  }

  const text = contactPromptForMissing(
    args.campaign,
    args.ask,
    args.enrollment.participant_username,
  );

  const sendResult = needsFirstContactDm(args.enrollment)
    ? await sendLeadMagnetDm(admin, {
      platform: args.enrollment.platform,
      organizationId: args.enrollment.organization_id,
      accountId: args.campaign.account_id,
      pageId: args.pageId,
      accessToken: args.accessToken,
      recipientScopedId: args.enrollment.participant_scoped_id,
      participantUsername: args.enrollment.participant_username,
      text,
      existingConversationId: args.enrollment.conversation_id,
      commentIdForPrivateReply: args.enrollment.comment_id?.trim() || null,
      deferPersistence: false,
    })
    : await sendLeadMagnetDm(admin, {
      platform: args.enrollment.platform,
      organizationId: args.enrollment.organization_id,
      accountId: args.campaign.account_id,
      pageId: args.pageId,
      accessToken: args.accessToken,
      recipientScopedId: args.enrollment.participant_scoped_id,
      participantUsername: args.enrollment.participant_username,
      text,
      existingConversationId: args.enrollment.conversation_id,
      deferPersistence: false,
    });

  if (!sendResult.ok) {
    await updateEnrollmentStatus(admin, args.enrollment.id, "failed", {
      last_error: sendResult.error ?? "Contact prompt DM failed",
    });
    return false;
  }

  await updateEnrollmentStatus(admin, args.enrollment.id, "awaiting_contact", {
    conversation_id: sendResult.conversationId ?? args.enrollment.conversation_id,
    conversation_table: args.enrollment.platform === "instagram"
      ? "instagram_conversations"
      : "facebook_conversations",
  });

  await logLeadMagnetFunnelEvent(admin, {
    enrollmentId: args.enrollment.id,
    campaignId: args.campaign.id,
    organizationId: args.enrollment.organization_id,
    eventType: "contact_prompt_sent",
    metadata: { ask: args.ask },
  });

  return true;
}

export async function sendContactInvalidReply(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    accessToken: string;
    pageId: string;
  },
): Promise<void> {
  const text = interpolateCampaignText(
    args.campaign.contact_invalid_text?.trim()
      || LEAD_MAGNET_DEFAULT_MESSAGES.contact_invalid_text
      || DEFAULT_CONTACT_INVALID,
    args.enrollment.participant_username,
  );

  await sendLeadMagnetDm(admin, {
    platform: args.enrollment.platform,
    organizationId: args.enrollment.organization_id,
    accountId: args.campaign.account_id,
    pageId: args.pageId,
    accessToken: args.accessToken,
    recipientScopedId: args.enrollment.participant_scoped_id,
    participantUsername: args.enrollment.participant_username,
    text,
    existingConversationId: args.enrollment.conversation_id,
    deferPersistence: false,
  });

  await logLeadMagnetFunnelEvent(admin, {
    enrollmentId: args.enrollment.id,
    campaignId: args.campaign.id,
    organizationId: args.enrollment.organization_id,
    eventType: "contact_invalid",
  });
}

import type { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";
import { parseContactReply } from "./parseContactReply.ts";
import type { ParsedContact } from "./parseContactReply.ts";
import {
  getParticipantProfile,
  syncSubmissionContactFields,
  upsertParticipantContactField,
} from "./participantProfile.ts";
import { getMissingContactFields } from "./skipMatrix.ts";
import { sendContactInvalidReply } from "./contactGatePrompt.ts";
import { orchestrateDeliveryAfterContact } from "../delivery/deliveryOrchestrator.ts";
import { logLeadMagnetFunnelEvent, updateEnrollmentStatus } from "../funnelAnalytics.ts";
import type { LeadMagnetCampaignRow, LeadMagnetEnrollmentRow } from "../types.ts";

export type ContactGateMatchMode = "awaiting" | "supplemental";

/** Mid-async recovery only — delivered_* are terminal (no supplemental contact on same enrollment). */
const SUPPLEMENTAL_DELIVERY_STATUSES = [
  "contact_collected",
] as const;

const SUPPLEMENTAL_QUERY_STATUSES = [
  ...SUPPLEMENTAL_DELIVERY_STATUSES,
  "comment_replied",
] as const;

function joinEnrollmentCampaign(row: Record<string, unknown>): {
  enrollment: LeadMagnetEnrollmentRow;
  campaign: LeadMagnetCampaignRow;
} | null {
  const joined = row as LeadMagnetEnrollmentRow & {
    campaign: LeadMagnetCampaignRow | LeadMagnetCampaignRow[] | null;
  };
  const campaignRaw = joined.campaign;
  const campaign = Array.isArray(campaignRaw) ? campaignRaw[0] : campaignRaw;
  if (!campaign?.contact_gate_enabled) return null;
  return { enrollment: joined as LeadMagnetEnrollmentRow, campaign };
}

function parsedMatchesMissingField(
  parsed: ParsedContact,
  missing: ReturnType<typeof getMissingContactFields>,
): boolean {
  if (!missing || parsed.kind === "invalid") return false;
  if (missing === "any") return parsed.kind === "phone" || parsed.kind === "email";
  return parsed.kind === missing;
}

function qualifiesForSupplementalMatch(
  status: string,
  parsed: ParsedContact,
  missing: ReturnType<typeof getMissingContactFields>,
): boolean {
  if (!parsedMatchesMissingField(parsed, missing)) return false;
  if (SUPPLEMENTAL_DELIVERY_STATUSES.includes(
    status as typeof SUPPLEMENTAL_DELIVERY_STATUSES[number],
  )) {
    return true;
  }
  // Stuck after partial delivery (e.g. comment_replied race) — not early "any" gate.
  if (status === "comment_replied" && missing && missing !== "any") {
    return true;
  }
  return false;
}

export async function handleInboundContact(
  admin: SupabaseClient,
  args: {
    enrollment: LeadMagnetEnrollmentRow;
    campaign: LeadMagnetCampaignRow;
    accessToken: string;
    pageId: string;
    messageBody: string;
    mode?: ContactGateMatchMode;
  },
): Promise<boolean> {
  const mode = args.mode ?? "awaiting";

  if (mode === "awaiting" && args.enrollment.status !== "awaiting_contact") {
    return false;
  }
  if (mode === "supplemental" && !SUPPLEMENTAL_QUERY_STATUSES.includes(
    args.enrollment.status as typeof SUPPLEMENTAL_QUERY_STATUSES[number],
  )) {
    return false;
  }
  if (!args.campaign.contact_gate_enabled) {
    return false;
  }

  const parsed = parseContactReply(args.messageBody);
  if (parsed.kind === "invalid") {
    if (mode === "awaiting") {
      await sendContactInvalidReply(admin, args);
      return true;
    }
    return false;
  }

  const profile = await getParticipantProfile(admin, {
    organizationId: args.enrollment.organization_id,
    platform: args.enrollment.platform,
    participantScopedId: args.enrollment.participant_scoped_id,
  });

  const missingBefore = getMissingContactFields(profile ?? { phone_number: null, email: null });
  if (!parsedMatchesMissingField(parsed, missingBefore)) {
    if (mode === "awaiting") {
      await sendContactInvalidReply(admin, args);
      return true;
    }
    return false;
  }

  const now = new Date().toISOString();
  const phonePatch = parsed.kind === "phone" ? parsed.normalized : undefined;
  const emailPatch = parsed.kind === "email" ? parsed.normalized : undefined;

  await upsertParticipantContactField(admin, {
    organizationId: args.enrollment.organization_id,
    platform: args.enrollment.platform,
    participantScopedId: args.enrollment.participant_scoped_id,
    phoneNumber: phonePatch ?? profile?.phone_number ?? null,
    email: emailPatch ?? profile?.email ?? null,
    canonicalLeadId: args.enrollment.lead_id,
    canonicalSubmissionId: args.enrollment.lead_submission_id,
  });

  await syncSubmissionContactFields(admin, args.enrollment.lead_submission_id, {
    phoneNumber: phonePatch ?? profile?.phone_number ?? null,
    email: emailPatch ?? profile?.email ?? null,
    leadMagnetCampaignName: args.campaign.name,
    leadMagnetTargetMarket: args.campaign.target_market,
  });

  await updateEnrollmentStatus(admin, args.enrollment.id, "contact_collected", {
    updated_at: now,
  });

  const deliveryChannel = parsed.kind === "phone" ? "whatsapp" : "email";
  await logLeadMagnetFunnelEvent(admin, {
    enrollmentId: args.enrollment.id,
    campaignId: args.campaign.id,
    organizationId: args.enrollment.organization_id,
    eventType: "contact_collected",
    metadata: {
      kind: parsed.kind,
      delivery_channel: deliveryChannel,
      delivery_scheduled: true,
      supplemental: mode === "supplemental",
    },
  });

  await orchestrateDeliveryAfterContact(admin, {
    enrollment: { ...args.enrollment, status: "contact_collected" },
    campaign: args.campaign,
    accessToken: args.accessToken,
    pageId: args.pageId,
    collectedKind: parsed.kind,
    phoneDigits: parsed.kind === "phone" ? parsed.normalized : undefined,
    email: parsed.kind === "email" ? parsed.normalized : undefined,
  });

  return true;
}

async function findAwaitingContactRows(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    participantScopedId: string;
  },
): Promise<Array<{ enrollment: LeadMagnetEnrollmentRow; campaign: LeadMagnetCampaignRow }>> {
  const { data: rows } = await admin
    .from("lead_magnet_enrollments")
    .select("*, campaign:lead_magnet_campaigns(*)")
    .eq("organization_id", args.organizationId)
    .eq("participant_scoped_id", args.participantScopedId)
    .eq("status", "awaiting_contact")
    .order("updated_at", { ascending: false })
    .limit(5);

  const matches: Array<{ enrollment: LeadMagnetEnrollmentRow; campaign: LeadMagnetCampaignRow }> = [];
  for (const row of rows ?? []) {
    const joined = joinEnrollmentCampaign(row as Record<string, unknown>);
    if (joined) matches.push(joined);
  }
  return matches;
}

export async function findActiveContactGateEnrollment(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    participantScopedId: string;
    messageBody: string;
  },
): Promise<{
  enrollment: LeadMagnetEnrollmentRow;
  campaign: LeadMagnetCampaignRow;
  mode: ContactGateMatchMode;
} | null> {
  const parsed = parseContactReply(args.messageBody);

  const awaitingMatches = await findAwaitingContactRows(admin, args);
  if (awaitingMatches.length > 0) {
    const first = awaitingMatches[0];
    return { ...first, mode: "awaiting" };
  }

  if (parsed.kind === "invalid") return null;

  const { data: rows } = await admin
    .from("lead_magnet_enrollments")
    .select("*, campaign:lead_magnet_campaigns(*)")
    .eq("organization_id", args.organizationId)
    .eq("participant_scoped_id", args.participantScopedId)
    .in("status", [...SUPPLEMENTAL_QUERY_STATUSES])
    .order("updated_at", { ascending: false })
    .limit(5);

  for (const row of rows ?? []) {
    const joined = joinEnrollmentCampaign(row as Record<string, unknown>);
    if (!joined) continue;

    const profile = await getParticipantProfile(admin, {
      organizationId: args.organizationId,
      platform: joined.enrollment.platform,
      participantScopedId: args.participantScopedId,
    });
    const missing = getMissingContactFields(profile ?? { phone_number: null, email: null });
    if (qualifiesForSupplementalMatch(joined.enrollment.status, parsed, missing)) {
      return { ...joined, mode: "supplemental" };
    }
  }

  return null;
}

/** @deprecated Use findActiveContactGateEnrollment */
export async function findAwaitingContactEnrollment(
  admin: SupabaseClient,
  args: {
    organizationId: string;
    participantScopedId: string;
  },
): Promise<{ enrollment: LeadMagnetEnrollmentRow; campaign: LeadMagnetCampaignRow } | null> {
  const matches = await findAwaitingContactRows(admin, args);
  return matches[0] ?? null;
}

export type ParsedContact =
  | { kind: "phone"; normalized: string; raw: string }
  | { kind: "email"; normalized: string; raw: string }
  | { kind: "invalid" };

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/i;

/** Indonesia-friendly WA digit normalization (mirrors frontend normalizeWaPhoneKey). */
export function normalizeWaPhoneDigits(input: string): string | null {
  const raw = input.trim();
  if (!raw) return null;
  let d = raw.replace(/\D/g, "");
  if (!d) return null;
  if (d.startsWith("0") && d.length >= 10) d = `62${d.slice(1)}`;
  if (!d.startsWith("62") && d.startsWith("8") && d.length >= 9 && d.length <= 12) d = `62${d}`;
  if (d.length < 8 || d.length > 18) return null;
  return d;
}

function extractEmailCandidate(text: string): string | null {
  const match = text.match(/[^\s@]+@[^\s@]+\.[^\s@]+/);
  if (!match) return null;
  const email = match[0].trim().toLowerCase();
  return EMAIL_RE.test(email) ? email : null;
}

function extractPhoneCandidate(text: string): string | null {
  const digitRuns = text.match(/(?:\+?\d[\d\s().-]{6,}\d|\d{8,18})/g);
  if (!digitRuns?.length) return null;
  for (const run of digitRuns) {
    const normalized = normalizeWaPhoneDigits(run);
    if (normalized) return normalized;
  }
  return null;
}

/**
 * Parse a single inbound DM for phone or email.
 * If both appear, prefer phone (WA priority per product spec).
 */
export function parseContactReply(messageBody: string): ParsedContact {
  const text = messageBody.trim();
  if (!text) return { kind: "invalid" };

  const phone = extractPhoneCandidate(text);
  if (phone) {
    return { kind: "phone", normalized: phone, raw: text };
  }

  const email = extractEmailCandidate(text);
  if (email) {
    return { kind: "email", normalized: email, raw: text };
  }

  return { kind: "invalid" };
}
